     7	/** The companies with an agreement, by code, and their discount. */
     8	final class CorporatePlan implements RatePlanPolicy {
     9	
    10	    private static final Map<String, BigDecimal> DISCOUNT_BY_COMPANY = Map.of(
    11	            "TECNOSUL", new BigDecimal("0.12"),
    12	            "AGROVALE", new BigDecimal("0.18"),
    13	            "FARMAVIDA", new BigDecimal("0.25"));
    14	
    15	    @Override
    16	    public void validate(Room room, NewReservation request) {
    17	        if (request.companyCode() == null || !DISCOUNT_BY_COMPANY.containsKey(request.companyCode())) {
    18	            throw new HotelException(ErrorCode.INVALID_REQUEST,
    19	                    "the CORPORATE plan needs the code of a company with an agreement");
    20	        }
    21	    }
    22	
    23	    @Override
    24	    public Price price(Room room, NewReservation request, NightlyCharges charges) {
    25	        return PercentOff.of(charges, DISCOUNT_BY_COMPANY.get(request.companyCode()));
    26	    }
    27	
    28	    @Override
    29	    public BigDecimal refund(Reservation reservation) {
