     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final RatePlans ratePlans;
    18	    private final EmailSender emailSender;
    19	
    20	    public ReservationService(Rooms rooms, ReservationStore store, PriceCalculator priceCalculator,
    21	            RatePlans ratePlans, EmailSender emailSender) {
    22	        this.rooms = rooms;
    23	        this.store = store;
    24	        this.priceCalculator = priceCalculator;
    25	        this.ratePlans = ratePlans;
    26	        this.emailSender = emailSender;
    27	    }
    28	
    29	    public synchronized Reservation create(NewReservation request) {
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    32	        }
    33	        if (request.guests() < 1) {
    34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    35	        }
    36	        Room room = rooms.find(request.roomNumber())
    37	                .orElseThrow(() -> new HotelException(
    38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    39	        if (request.guests() > room.capacity()) {
    40	            throw new HotelException(
    41	                    ErrorCode.CAPACITY_EXCEEDED,
    42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    43	        }
    44	        boolean roomTaken = store.all().stream()
    45	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    46	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    47	        if (roomTaken) {
    48	            throw new HotelException(
    49	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    50	        }
    51	        Price price = priceCalculator.calculate(room, request);
    52	        Reservation reservation = new Reservation(store.nextId(), request, price);
    53	        store.save(reservation);
    54	        return reservation;
    55	    }
    56	
    57	    public Reservation find(long reservationId) {
    58	        return store.find(reservationId)
    59	                .orElseThrow(() -> new HotelException(
    60	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    61	    }
    62	
    63	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    64	    public synchronized Reservation confirm(long reservationId) {
    65	        Reservation reservation = find(reservationId);
    66	        if (reservation.status() != ReservationStatus.PENDING) {
    67	            throw notAllowed(reservation, "confirm");
    68	        }
    69	        reservation.confirmPayment();
    70	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    71	        emailSender.send(
    72	                reservation.guest().email(),
    73	                "Reserva confirmada - " + HOTEL_NAME,
    74	                confirmationEmailBody(reservation, receipt));
    75	        return reservation;
    76	    }
    77	
    78	    /**
    79	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    80	     * reservation was never paid, so nothing comes back).
    81	     */
    82	    public synchronized Reservation cancel(long reservationId) {
    83	        Reservation reservation = find(reservationId);
    84	        if (reservation.status() != ReservationStatus.PENDING
    85	                && reservation.status() != ReservationStatus.CONFIRMED) {
    86	            throw notAllowed(reservation, "cancel");
    87	        }
    88	        BigDecimal refund = ratePlans.policyFor(reservation.ratePlan()).refund(reservation);
    89	        reservation.cancel(refund);
    90	        return reservation;
    91	    }
    92	
    93	    public synchronized Reservation checkIn(long reservationId) {
    94	        Reservation reservation = find(reservationId);
    95	        if (reservation.status() != ReservationStatus.CONFIRMED) {
    96	            throw notAllowed(reservation, "check in");
    97	        }
    98	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
    99	        return reservation;
   100	    }
   101	
   102	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   103	    public synchronized ReservationReceipt checkOut(long reservationId) {
   104	        Reservation reservation = find(reservationId);
   105	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   106	            throw notAllowed(reservation, "check out");
   107	        }
   108	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   109	        return new ReservationReceipt(reservation, roomOf(reservation));
   110	    }
   111	
   112	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   113	    public ReservationReceipt receiptCopy(long reservationId) {
   114	        Reservation reservation = find(reservationId);
   115	        if (!reservation.isPaid()) {
   116	            throw notAllowed(reservation, "issue a receipt for");
   117	        }
   118	        return new ReservationReceipt(reservation, roomOf(reservation));
   119	    }
   120	
   121	    private Room roomOf(Reservation reservation) {
   122	        return rooms.find(reservation.roomNumber()).orElseThrow();
   123	    }
   124	
   125	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   126	        return "Olá, " + reservation.guest().name() + "!\n\n"
   127	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   128	                + receipt.text() + "\n"
